using CwcConfigurator.Services;
using Xunit;

namespace CwcConfigurator.Tests;

public class ScadaInternalTagModuleTests
{
    // Mirrors the real AUX_FUNCTIONS.hmi.js shape: global definition area + protected
    // marker + the owned function (with a brace inside a string and inside a comment to
    // stress the scanner) + a trailing second function that must be preserved.
    private const string Module =
        "export let GLOBAL_A = 1;\n" +
        "export let GLOBAL_B = \"x\";\n" +
        "/*<auto-generated>\n***End of Global definition area***\n</auto-generated>*/\n" +
        "export function _SET_INTERNAL_TAG(parameter1, parameter2) {\n" +
        "let NAME = \"value with } brace\";  //  comment with { brace\n" +
        "let N = 5;\n" +
        "Tags.SysFct.SetTagValue(\"TAG\", N);\n" +
        "}\n" +
        "\n" +
        "export function OTHER() {\n" +
        "let z = 1;\n" +
        "}\n";

    [Fact]
    public void Split_IsolatesOwnedFunctionBody()
    {
        var module = ScadaInternalTagModule.Split(Module);

        Assert.Equal("_SET_INTERNAL_TAG", module.FunctionName);
        Assert.EndsWith("_SET_INTERNAL_TAG(parameter1, parameter2) {", module.Header.TrimEnd());
        Assert.Contains("End of Global definition area", module.Header);

        // Body holds the owned content; the brace inside the string/comment must not end it.
        Assert.Contains("let NAME = \"value with } brace\"", module.Body);
        Assert.Contains("Tags.SysFct.SetTagValue(\"TAG\", N);", module.Body);
        Assert.DoesNotContain("export function OTHER", module.Body);

        // Footer keeps the closing brace and every sibling function verbatim.
        Assert.StartsWith("}", module.Footer);
        Assert.Contains("export function OTHER", module.Footer);
    }

    [Fact]
    public void Rewrap_WithOriginalBody_IsLossless()
    {
        var module = ScadaInternalTagModule.Split(Module);

        Assert.Equal(Module, module.Rewrap(module.Body));
    }

    [Fact]
    public void Rewrap_ReplacesOnlyTheBody()
    {
        var module = ScadaInternalTagModule.Split(Module);

        var rebuilt = module.Rewrap("\nlet NEW = 1;\n");

        Assert.Contains("let NEW = 1;", rebuilt);
        Assert.DoesNotContain("let NAME", rebuilt);
        // Global area, marker and the sibling function survive untouched.
        Assert.Contains("export let GLOBAL_A = 1;", rebuilt);
        Assert.Contains("End of Global definition area", rebuilt);
        Assert.Contains("export function OTHER", rebuilt);
    }

    [Fact]
    public void Split_MissingFunction_Throws()
    {
        Assert.Throws<InvalidOperationException>(
            () => ScadaInternalTagModule.Split("export function SOMETHING_ELSE() {\n}\n"));
    }
}
